<template><DeliveryShell title="配送工作台" :controller="controller"><template #identity><view v-if="identity" class="delivery-profile"><image v-if="identity.avatar" :src="userCenterMedia(identity.avatar)" class="delivery-avatar" mode="aspectFill" /><view class="delivery-stack"><text>{{ identity.nickname }}</text><text class="delivery-link" @tap="phone(identity.phone)">{{ identity.phone }}</text></view></view></template><view class="delivery-tabs"><button :class="{active:tab==='orders'}" @tap="chooseTab('orders')">配送订单</button><button :class="{active:tab==='daily'}" @tap="chooseTab('daily')">配送统计</button><button @tap="controller.go('scanning')">扫码 / 手动核对</button></view><view class="delivery-card"><text class="delivery-label">统计时间</text><picker :range="periods" range-key="label" :value="periodIndex" @change="changePeriod"><view class="delivery-selector">{{ periods[periodIndex]?.label }} · 选择</view></picker><view class="delivery-controls"><picker mode="date" fields="day" :value="startDate" @change="startDate=$event.detail.value"><view class="delivery-selector">{{ startDate||'起始日期' }}</view></picker><picker mode="date" fields="day" :value="endDate" @change="endDate=$event.detail.value"><view class="delivery-selector">{{ endDate||'结束日期' }}</view></picker><button @tap="applyRange">应用日期范围</button></view></view><view v-if="statistics" class="delivery-grid"><view class="delivery-metric" @tap="chooseStatus(1)"><text>待配送</text><text class="delivery-amount">{{ statistics.unsend }}</text></view><view class="delivery-metric" @tap="chooseStatus(2)"><text>已配送</text><text class="delivery-amount">{{ statistics.send }}</text></view><view class="delivery-metric" @tap="chooseTab('daily')"><text>已配送金额</text><text class="delivery-amount">¥{{ statistics.send_price }}</text></view></view><template v-if="tab==='orders'"><view class="delivery-tabs"><button :class="{active:status===1}" @tap="chooseStatus(1)">待配送 {{ orderCounts.unsend }}</button><button :class="{active:status===2}" @tap="chooseStatus(2)">已配送 {{ orderCounts.send }}</button></view><view v-for="order in orders" :key="order.id" class="delivery-card" @tap="controller.go('orderDetail',{orderId:order.id})"><view class="delivery-row"><text class="delivery-link">{{ order.order_id }}</text><text class="delivery-status">{{ order._status._title }}</text></view><DeliveryCart v-for="cart in order.cartInfo" :key="cart.id" :cart="cart" /><view class="delivery-row"><text>{{ order.total_num }} 件 · {{ order.real_name }}</text><text class="delivery-amount">¥{{ order.pay_price }}</text></view><text class="delivery-muted">{{ order.user_address }}</text></view><view v-if="!orders.length" class="delivery-empty">当前范围暂无配送订单</view><button v-if="ordersMore" :disabled="pageBusy" class="delivery-full-button" @tap="loadMoreOrders">加载更多订单</button></template><template v-else><view class="delivery-card"><view class="delivery-table-row"><text>日期</text><text>配送数量</text><text>配送金额</text></view><view v-for="row in daily" :key="row.date" class="delivery-table-row"><text>{{ row.time }}</text><text>{{ row.count }}</text><text>¥{{ row.price }}</text></view><text v-if="!daily.length" class="delivery-muted">当前时间范围暂无配送记录</text><button v-if="dailyMore" :disabled="pageBusy" class="delivery-full-button" @tap="loadMoreDaily">加载更多日期</button></view></template><view v-if="pageError" class="delivery-warning">{{ pageError }}</view></DeliveryShell></template>
<script setup lang="ts">
import {computed,ref} from 'vue';import {onReachBottom} from '@dcloudio/uni-app';import DeliveryShell from '@/components/deliveryWorkbench/DeliveryShell.vue';import DeliveryCart from '@/components/deliveryWorkbench/DeliveryCart.vue';import {useDeliveryWorkbench} from '@/composables/useDeliveryWorkbench';import {isDeliveryStatistics,isDeliveryOrders,isDeliveryDaily,deliverySameScope} from '@/utils/deliveryWorkbench';import {userCenterMedia} from '@/utils/userCenter';import type {DeliveryWorkbenchStatistics,DeliveryOrderItem,DeliveryDailyRow} from '@/types/deliveryWorkbench';
const tab=ref<'orders'|'daily'>('orders'),status=ref(1),statistics=ref<DeliveryWorkbenchStatistics|null>(null),orders=ref<DeliveryOrderItem[]>([]),daily=ref<DeliveryDailyRow[]>([]),orderCounts=ref({unsend:0,send:0}),ordersMore=ref(false),dailyMore=ref(false),pageBusy=ref(false),pageError=ref(''),periodIndex=ref(0),startDate=ref(''),endDate=ref('');let orderPage=1,dailyPage=1,dateQuery='today',dataEpoch=0;
const periods=[{label:'今天',value:'today'},{label:'昨天',value:'yesterday'},{label:'本月',value:'month'}];
const controller=useDeliveryWorkbench({clear(){dataEpoch++;statistics.value=null;orders.value=[];daily.value=[];orderCounts.value={unsend:0,send:0};ordersMore.value=false;dailyMore.value=false;pageBusy.value=false;pageError.value='';orderPage=1;dailyPage=1;},async load(c){const valid=c.fence(),generation=dataEpoch;const [stats,list,rows]=await Promise.all([c.read('statistics',isDeliveryStatistics,{data:dateQuery}),c.read('orders',isDeliveryOrders,{data:dateQuery,type:status.value,page:1,limit:15}),c.read('daily',isDeliveryDaily,{data:dateQuery,page:1,limit:15})]);if(!valid()||generation!==dataEpoch)return;statistics.value=stats.data;orders.value=list.data.list;orderCounts.value={unsend:list.data.unsend,send:list.data.send};ordersMore.value=list.data.has_more;daily.value=rows.data.list;dailyMore.value=rows.data.has_more;}});
const identity=computed(()=>controller.context.value?.data.contexts.find(row=>deliverySameScope(row,controller.selected.value)));
function chooseTab(value:'orders'|'daily'){tab.value=value;}function chooseStatus(value:1|2){status.value=value;tab.value='orders';void controller.load();}
function changePeriod(event:{detail:{value:string|number}}){const index=Number(event.detail.value);if(!periods[index])return;periodIndex.value=index;dateQuery=periods[index]!.value;startDate.value='';endDate.value='';void controller.load();}
function applyRange(){if(!/^\d{4}-\d{2}-\d{2}$/u.test(startDate.value)||!/^\d{4}-\d{2}-\d{2}$/u.test(endDate.value)||startDate.value>endDate.value){pageError.value='请选择有效的起止日期';return;}dateQuery=`${startDate.value}~${endDate.value}`;void controller.load();}
async function loadMoreOrders(){if(pageBusy.value||!ordersMore.value)return;pageBusy.value=true;pageError.value='';const valid=controller.fence(),generation=dataEpoch;try{const row=await controller.read('orders',isDeliveryOrders,{data:dateQuery,type:status.value,page:orderPage+1,limit:15});if(!valid()||generation!==dataEpoch)return;if(row.data.page!==orderPage+1||row.data.list.some(item=>orders.value.some(previous=>previous.id===item.id)))throw Error('订单分页发生变化，请刷新');orderPage++;orders.value.push(...row.data.list);ordersMore.value=row.data.has_more;}catch(failure){if(valid())pageError.value=failure instanceof Error?failure.message:'订单暂不可读';}finally{if(valid()&&generation===dataEpoch)pageBusy.value=false;}}
async function loadMoreDaily(){if(pageBusy.value||!dailyMore.value)return;pageBusy.value=true;pageError.value='';const valid=controller.fence(),generation=dataEpoch;try{const row=await controller.read('daily',isDeliveryDaily,{data:dateQuery,page:dailyPage+1,limit:15});if(!valid()||generation!==dataEpoch)return;if(row.data.page!==dailyPage+1||row.data.list.some(item=>daily.value.some(previous=>previous.date===item.date)))throw Error('统计分页发生变化，请刷新');dailyPage++;daily.value.push(...row.data.list);dailyMore.value=row.data.has_more;}catch(failure){if(valid())pageError.value=failure instanceof Error?failure.message:'统计暂不可读';}finally{if(valid()&&generation===dataEpoch)pageBusy.value=false;}}
function phone(value:string){if(controller.current()&&identity.value?.phone===value&&value)uni.makePhoneCall({phoneNumber:value});}
onReachBottom(()=>{if(tab.value==='orders')void loadMoreOrders();else void loadMoreDaily();});
</script>
